<!doctype html><title>Private ride trigger</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><main class="container py-4"><a href="/admin/whatsapp_workflow.php">← Workflow controls</a><div class="card mt-3"><div class="card-body"><h1 class="h4">Private message trigger</h1><p class="text-secondary">Keep ordinary family and friend messages from starting the ride bot.</p><form id="f"><label class="form-check mb-3"><input class="form-check-input" type="checkbox" name="trigger_private_mention" <?=($r['trigger_private_mention']??'1')==='1'?'checked':''?>> Require a tag for a new private ride request</label><label class="form-label">Tag users must include</label><input class="form-control" name="bot_mention" value="<?=htmlspecialchars($r['bot_mention']??'@ridebot')?>"><div class="form-text">Example: @ridebot Looking from Monsey going to Brooklyn call 8451234567</div><button class="btn btn-primary mt-3">Save</button><span id="s" class="ms-2"></span></form></div></div></main><script>f.onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(f));d.csrf='<?=htmlspecialchars($csrf)?>';let r=await fetch('/api/admin/whatsapp_private_control.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});s.textContent=r.ok?'Saved':'Error'}</script>
